import React, { useState, useMemo } from "react";
import { Btn, Card, Ic, ICONS } from "../components/UI";

export default function Calendar({ t, toast }) {
  const [viewMode, setViewMode] = useState("Month");
  const [currentDate, setCurrentDate] = useState(new Date(2026, 4, 1)); // May 2026
  const [selectedDate, setSelectedDate] = useState(null);
  const [events, setEvents] = useState([
    { id: 1, date: "2026-05-09", title: "Hearing: State v. Sharma", type: "hearing", time: "10:00 AM", court: "Delhi High Court" },
    { id: 2, date: "2026-05-15", title: "Filing Deadline: Evidence Bundle", type: "deadline", time: "5:00 PM", court: "N/A" },
    { id: 3, date: "2026-05-22", title: "Hearing: Rent Dispute", type: "hearing", time: "2:00 PM", court: "Tis Hazari Court" },
  ]);
  const [showModal, setShowModal] = useState(false);
  const [modalMode, setModalMode] = useState("add"); // "add" or "edit"
  const [editingEvent, setEditingEvent] = useState(null);
  const [formData, setFormData] = useState({ title: "", type: "hearing", time: "", court: "" });

  const monthNames = [
    "January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December"
  ];

  const days = ["SUN", "MON", "TUE", "WED", "THU", "FRI", "SAT"];

  // ── Calendar Math ─────────────────────────────────────────────────────────
  const calendarData = useMemo(() => {
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();

    const firstDayOfMonth = new Date(year, month, 1).getDay();
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    const daysInPrevMonth = new Date(year, month, 0).getDate();

    const prevDays = [];
    for (let i = firstDayOfMonth - 1; i >= 0; i--) {
      prevDays.push(daysInPrevMonth - i);
    }

    const currentDays = Array.from({ length: daysInMonth }, (_, i) => i + 1);

    const totalCells = prevDays.length + currentDays.length;
    const nextDaysCount = totalCells <= 35 ? 35 - totalCells : 42 - totalCells;
    const nextDays = Array.from({ length: nextDaysCount }, (_, i) => i + 1);

    return { prevDays, currentDays, nextDays, year, month };
  }, [currentDate]);

  const formatDateKey = (year, month, day) => {
    return `${year}-${String(month + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
  };

  const getEventsForDate = (year, month, day) => {
    const key = formatDateKey(year, month, day);
    return events.filter(e => e.date === key);
  };

  const getEventsForSelectedDate = () => {
    if (!selectedDate) return [];
    return getEventsForDate(selectedDate.year, selectedDate.month, selectedDate.day);
  };

  // ── Navigation ────────────────────────────────────────────────────────────
  const goToPrevMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
    setSelectedDate(null);
  };

  const goToNextMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));
    setSelectedDate(null);
  };

  const goToToday = () => {
    const today = new Date();
    setCurrentDate(new Date(today.getFullYear(), today.getMonth(), 1));
    setSelectedDate({ year: today.getFullYear(), month: today.getMonth(), day: today.getDate() });
  };

  // ── Event Management ──────────────────────────────────────────────────────
  const openAddModal = () => {
    if (!selectedDate) {
      toast("Please select a date first", "warn");
      return;
    }
    setModalMode("add");
    setEditingEvent(null);
    setFormData({ title: "", type: "hearing", time: "", court: "" });
    setShowModal(true);
  };

  const openEditModal = (event) => {
    setModalMode("edit");
    setEditingEvent(event);
    setFormData({
      title: event.title,
      type: event.type,
      time: event.time,
      court: event.court
    });
    setShowModal(true);
  };

  const saveEvent = () => {
    if (!formData.title.trim()) {
      toast("Title is required", "error");
      return;
    }

    const dateKey = selectedDate
      ? formatDateKey(selectedDate.year, selectedDate.month, selectedDate.day)
      : formatDateKey(currentDate.getFullYear(), currentDate.getMonth(), 1);

    if (modalMode === "add") {
      const newEvent = {
        id: Date.now(),
        date: dateKey,
        ...formData
      };
      setEvents([...events, newEvent]);
      toast("Event added successfully", "success");
    } else {
      setEvents(events.map(e => e.id === editingEvent.id ? { ...e, ...formData } : e));
      toast("Event updated", "success");
    }
    setShowModal(false);
  };

  const deleteEvent = (id) => {
    setEvents(events.filter(e => e.id !== id));
    toast("Event deleted", "success");
  };

  // ── Render Cell ───────────────────────────────────────────────────────────
  const renderCell = (num, isCurrentMonth, isPrev) => {
    const { year, month } = calendarData;
    const cellYear = isPrev ? (month === 0 ? year - 1 : year) : (isCurrentMonth ? year : (month === 11 ? year + 1 : year));
    const cellMonth = isPrev ? (month === 0 ? 11 : month - 1) : (isCurrentMonth ? month : (month === 11 ? 0 : month + 1));

    const dateKey = formatDateKey(cellYear, cellMonth, num);
    const dayEvents = events.filter(e => e.date === dateKey);
    const isSelected = selectedDate && selectedDate.year === cellYear && selectedDate.month === cellMonth && selectedDate.day === num;
    const isToday = new Date().toDateString() === new Date(cellYear, cellMonth, num).toDateString();

    return (
      <div
        key={`${isCurrentMonth ? "curr" : isPrev ? "prev" : "next"}-${num}`}
        onClick={() => setSelectedDate({ year: cellYear, month: cellMonth, day: num })}
        style={{
          minHeight: 100,
          padding: "8px 12px",
          borderRight: `1px solid ${t.border}`,
          borderBottom: `1px solid ${t.border}`,
          color: isCurrentMonth ? t.text : t.sub,
          opacity: isCurrentMonth ? 1 : 0.35,
          fontSize: 13,
          fontWeight: 600,
          display: "flex",
          flexDirection: "column",
          alignItems: "flex-start",
          background: isSelected
            ? (t === "dark" ? "rgba(234, 88, 12, 0.15)" : "rgba(234, 88, 12, 0.08)")
            : isToday
              ? (t === "dark" ? "rgba(59, 130, 246, 0.1)" : "rgba(59, 130, 246, 0.05)")
              : "transparent",
          cursor: "pointer",
          transition: "background 0.15s",
          position: "relative"
        }}
        onMouseEnter={e => { if (!isSelected) e.currentTarget.style.background = t === "dark" ? "rgba(255,255,255,0.03)" : "rgba(0,0,0,0.02)"; }}
        onMouseLeave={e => {
          e.currentTarget.style.background = isSelected
            ? (t === "dark" ? "rgba(234, 88, 12, 0.15)" : "rgba(234, 88, 12, 0.08)")
            : isToday
              ? (t === "dark" ? "rgba(59, 130, 246, 0.1)" : "rgba(59, 130, 246, 0.05)")
              : "transparent";
        }}
      >
        <div style={{
          width: 26, height: 26, borderRadius: "50%",
          display: "flex", alignItems: "center", justifyContent: "center",
          background: isSelected ? "#ea580c" : isToday ? "#3b82f6" : "transparent",
          color: (isSelected || isToday) ? "#fff" : "inherit",
          fontSize: 12,
          marginBottom: 4
        }}>
          {num}
        </div>

        {/* Event dots/indicators */}
        <div style={{ display: "flex", flexDirection: "column", gap: 3, width: "100%" }}>
          {dayEvents.slice(0, 2).map(ev => (
            <div key={ev.id} style={{
              fontSize: 10,
              fontWeight: 600,
              padding: "2px 6px",
              borderRadius: 4,
              background: ev.type === "hearing" ? (t === "dark" ? "rgba(234, 88, 12, 0.25)" : "rgba(234, 88, 12, 0.12)") : (t === "dark" ? "rgba(239, 68, 68, 0.25)" : "rgba(239, 68, 68, 0.12)"),
              color: ev.type === "hearing" ? "#ea580c" : "#ef4444",
              whiteSpace: "nowrap",
              overflow: "hidden",
              textOverflow: "ellipsis"
            }}>
              {ev.title}
            </div>
          ))}
          {dayEvents.length > 2 && (
            <div style={{ fontSize: 10, color: t.sub, paddingLeft: 4 }}>+{dayEvents.length - 2} more</div>
          )}
        </div>
      </div>
    );
  };

  // ── List View ─────────────────────────────────────────────────────────────
  const renderListView = () => {
    const sortedEvents = [...events].sort((a, b) => new Date(a.date) - new Date(b.date));

    return (
      <Card t={t} style={{ padding: 0, overflow: "hidden" }}>
        <div style={{ padding: "20px 24px", borderBottom: `1px solid ${t.border}` }}>
          <h2 style={{ fontSize: 18, fontWeight: 700, margin: 0, color: t.text }}>
            All Events ({sortedEvents.length})
          </h2>
        </div>
        <div style={{ padding: "16px 24px" }}>
          {sortedEvents.length === 0 ? (
            <div style={{ textAlign: "center", color: t.sub, padding: 40 }}>No events scheduled</div>
          ) : (
            <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
              {sortedEvents.map(ev => {
                const evDate = new Date(ev.date);
                return (
                  <div key={ev.id} style={{
                    display: "flex",
                    alignItems: "center",
                    gap: 16,
                    padding: "14px 16px",
                    borderRadius: 10,
                    border: `1px solid ${t.border}`,
                    background: t.surface
                  }}>
                    <div style={{
                      width: 48, height: 48, borderRadius: 10,
                      background: ev.type === "hearing" ? (t === "dark" ? "rgba(234, 88, 12, 0.2)" : "rgba(234, 88, 12, 0.1)") : (t === "dark" ? "rgba(239, 68, 68, 0.2)" : "rgba(239, 68, 68, 0.1)"),
                      display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center",
                      color: ev.type === "hearing" ? "#ea580c" : "#ef4444",
                      fontWeight: 800,
                      fontSize: 12,
                      flexShrink: 0
                    }}>
                      <div>{evDate.toLocaleString("default", { month: "short" })}</div>
                      <div style={{ fontSize: 16 }}>{evDate.getDate()}</div>
                    </div>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ fontWeight: 700, fontSize: 14, color: t.text, marginBottom: 4 }}>{ev.title}</div>
                      <div style={{ fontSize: 12, color: t.sub, display: "flex", gap: 12, flexWrap: "wrap" }}>
                        <span style={{ display: "flex", alignItems: "center", gap: 4 }}>
                          <Ic d={ICONS.clock} size={12} color={t.sub} /> {ev.time}
                        </span>
                        <span style={{ display: "flex", alignItems: "center", gap: 4 }}>
                          <Ic d={ICONS.mapPin} size={12} color={t.sub} /> {ev.court}
                        </span>
                        <span style={{
                          padding: "2px 8px", borderRadius: 4, fontSize: 10, fontWeight: 700,
                          background: ev.type === "hearing" ? (t === "dark" ? "rgba(234, 88, 12, 0.2)" : "rgba(234, 88, 12, 0.1)") : (t === "dark" ? "rgba(239, 68, 68, 0.2)" : "rgba(239, 68, 68, 0.1)"),
                          color: ev.type === "hearing" ? "#ea580c" : "#ef4444",
                          textTransform: "uppercase"
                        }}>
                          {ev.type}
                        </span>
                      </div>
                    </div>
                    <div style={{ display: "flex", gap: 6, flexShrink: 0 }}>
                      <button
                        onClick={() => openEditModal(ev)}
                        style={{
                          width: 32, height: 32, borderRadius: 6, border: `1px solid ${t.border}`,
                          background: "transparent", color: t.sub, cursor: "pointer",
                          display: "flex", alignItems: "center", justifyContent: "center"
                        }}
                      >
                        <Ic d={ICONS.edit} size={14} />
                      </button>
                      <button
                        onClick={() => deleteEvent(ev.id)}
                        style={{
                          width: 32, height: 32, borderRadius: 6, border: `1px solid ${t.border}`,
                          background: "transparent", color: "#ef4444", cursor: "pointer",
                          display: "flex", alignItems: "center", justifyContent: "center"
                        }}
                      >
                        <Ic d={ICONS.trash} size={14} />
                      </button>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </Card>
    );
  };

  const { prevDays, currentDays, nextDays, year, month } = calendarData;
  const selectedEvents = getEventsForSelectedDate();

  return (
    <div style={{ maxWidth: 1200, margin: "40px auto", padding: "0 24px", minHeight: "calc(100vh - 60px - 40px)" }}>
      {/* Header */}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 32, flexWrap: "wrap", gap: 16 }}>
        <div>
          <h1 style={{ fontSize: 24, fontWeight: 800, color: t.text, margin: "0 0 6px" }}>Calendar</h1>
          <p style={{ fontSize: 14, color: t.sub, margin: 0 }}>Hearings & deadlines across all matters</p>
        </div>
        <div style={{ display: "flex", gap: 12, alignItems: "center", flexWrap: "wrap" }}>
          {/* View Toggles */}
          <div style={{ display: "flex", background: t.surface, border: `1px solid ${t.border}`, borderRadius: 8, padding: 4 }}>
            {["Month", "List"].map(m => (
              <button
                key={m}
                onClick={() => setViewMode(m)}
                style={{
                  background: viewMode === m ? (t === "dark" ? "rgba(255,255,255,0.05)" : "rgba(0,0,0,0.04)") : "transparent",
                  color: viewMode === m ? t.text : t.sub,
                  border: "none", borderRadius: 6, padding: "6px 14px", fontSize: 13, fontWeight: 600,
                  cursor: "pointer", transition: "all 0.2s", display: "flex", alignItems: "center", gap: 6
                }}
              >
                {m === "Month" && <Ic d={ICONS.grid} size={14} color="inherit" />}
                {m === "List" && <Ic d={ICONS.menu} size={14} color="inherit" />}
                {m}
              </button>
            ))}
          </div>

          <button
            onClick={openAddModal}
            style={{
              background: "#ea580c", color: "#fff",
              border: "none", borderRadius: 8, padding: "10px 18px", fontSize: 13, fontWeight: 700,
              cursor: "pointer", display: "flex", alignItems: "center", gap: 6, transition: "all 0.2s"
            }}
          >
            + Hearing
          </button>
          <Btn t={t} onClick={openAddModal}>+ Deadline</Btn>
        </div>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: viewMode === "List" ? "1fr" : "1fr 300px", gap: 24 }}>
        {/* Calendar Grid area */}
        {viewMode === "Month" ? (
          <Card t={t} style={{ padding: 0, overflow: "hidden" }}>
            {/* Month Navigation */}
            <div style={{ padding: "20px 24px", display: "flex", alignItems: "center", justifyContent: "space-between", borderBottom: `1px solid ${t.border}` }}>
              <div style={{ display: "flex", alignItems: "center", gap: 16 }}>
                <button
                  onClick={goToPrevMonth}
                  style={{ background: "none", border: "none", cursor: "pointer", color: t.sub, padding: 4, borderRadius: 6, transition: "background 0.15s" }}
                  onMouseEnter={e => e.currentTarget.style.background = t === "dark" ? "rgba(255,255,255,0.05)" : "rgba(0,0,0,0.04)"}
                  onMouseLeave={e => e.currentTarget.style.background = "transparent"}
                >
                  <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="15 18 9 12 15 6"></polyline></svg>
                </button>
                <h2 style={{ fontSize: 18, fontWeight: 700, margin: 0, minWidth: 140, textAlign: "center", color: t.text }}>
                  {monthNames[month]} {year}
                </h2>
                <button
                  onClick={goToNextMonth}
                  style={{ background: "none", border: "none", cursor: "pointer", color: t.sub, padding: 4, borderRadius: 6, transition: "background 0.15s" }}
                  onMouseEnter={e => e.currentTarget.style.background = t === "dark" ? "rgba(255,255,255,0.05)" : "rgba(0,0,0,0.04)"}
                  onMouseLeave={e => e.currentTarget.style.background = "transparent"}
                >
                  <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="9 18 15 12 9 6"></polyline></svg>
                </button>
              </div>
              <button
                onClick={goToToday}
                style={{
                  background: "transparent", border: `1px solid ${t.border}`, borderRadius: 8,
                  padding: "6px 14px", fontSize: 13, fontWeight: 600, color: t.text, cursor: "pointer",
                  transition: "all 0.15s"
                }}
                onMouseEnter={e => { e.currentTarget.style.borderColor = t.blue; e.currentTarget.style.color = t.blue; }}
                onMouseLeave={e => { e.currentTarget.style.borderColor = t.border; e.currentTarget.style.color = t.text; }}
              >
                Today
              </button>
            </div>

            {/* Days Header */}
            <div style={{ display: "grid", gridTemplateColumns: "repeat(7, 1fr)", borderBottom: `1px solid ${t.border}` }}>
              {days.map(d => (
                <div key={d} style={{ padding: "12px", textAlign: "center", fontSize: 11, fontWeight: 700, color: t.sub, letterSpacing: "0.05em", borderRight: `1px solid ${t.border}` }}>
                  {d}
                </div>
              ))}
            </div>

            {/* Grid */}
            <div style={{ display: "grid", gridTemplateColumns: "repeat(7, 1fr)" }}>
              {prevDays.map(d => renderCell(d, false, true))}
              {currentDays.map(d => renderCell(d, true, false))}
              {nextDays.map(d => renderCell(d, false, false))}
            </div>
          </Card>
        ) : (
          renderListView()
        )}

        {/* Right Sidebar - only show in Month view */}
        {viewMode === "Month" && (
          <div>
            <h3 style={{ fontSize: 16, fontWeight: 700, margin: "0 0 16px", color: t.text }}>
              {selectedDate
                ? `${monthNames[selectedDate.month]} ${selectedDate.day}, ${selectedDate.year}`
                : "Select a date"
              }
            </h3>

            {selectedDate ? (
              <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
                {selectedEvents.length === 0 ? (
                  <div style={{
                    padding: "24px 16px",
                    textAlign: "center",
                    color: t.sub,
                    fontSize: 14,
                    border: `1px dashed ${t.border}`,
                    borderRadius: 10
                  }}>
                    <div style={{ marginBottom: 8, opacity: 0.5 }}>
                      <Ic d={ICONS.calendar} size={32} color={t.sub} />
                    </div>
                    No events on this day
                    <br />
                    <button
                      onClick={openAddModal}
                      style={{
                        marginTop: 12,
                        background: "none",
                        border: "none",
                        color: t.blue,
                        fontSize: 13,
                        fontWeight: 600,
                        cursor: "pointer",
                        textDecoration: "underline"
                      }}
                    >
                      Add an event
                    </button>
                  </div>
                ) : (
                  selectedEvents.map(ev => (
                    <div key={ev.id} style={{
                      padding: "14px 16px",
                      borderRadius: 10,
                      border: `1px solid ${t.border}`,
                      background: t.surface,
                      cursor: "pointer",
                      transition: "all 0.15s"
                    }}
                      onClick={() => openEditModal(ev)}
                      onMouseEnter={e => e.currentTarget.style.borderColor = t.blue}
                      onMouseLeave={e => e.currentTarget.style.borderColor = t.border}
                    >
                      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8 }}>
                        <div style={{
                          width: 8, height: 8, borderRadius: "50%",
                          background: ev.type === "hearing" ? "#ea580c" : "#ef4444",
                          flexShrink: 0
                        }} />
                        <span style={{ fontSize: 10, fontWeight: 700, textTransform: "uppercase", color: ev.type === "hearing" ? "#ea580c" : "#ef4444" }}>
                          {ev.type}
                        </span>
                      </div>
                      <div style={{ fontWeight: 700, fontSize: 14, color: t.text, marginBottom: 6 }}>{ev.title}</div>
                      <div style={{ fontSize: 12, color: t.sub, display: "flex", flexDirection: "column", gap: 4 }}>
                        <span style={{ display: "flex", alignItems: "center", gap: 6 }}>
                          <Ic d={ICONS.clock} size={12} color={t.sub} /> {ev.time}
                        </span>
                        <span style={{ display: "flex", alignItems: "center", gap: 6 }}>
                          <Ic d={ICONS.mapPin} size={12} color={t.sub} /> {ev.court}
                        </span>
                      </div>
                    </div>
                  ))
                )}
              </div>
            ) : (
              <div style={{ textAlign: "center", color: t.sub, marginTop: 40, fontSize: 14, padding: "20px", border: `1px dashed ${t.border}`, borderRadius: 10 }}>
                <Ic d={ICONS.calendar} size={32} color={t.sub} style={{ opacity: 0.5, marginBottom: 8 }} />
                <div>Click on any date to view or add events</div>
              </div>
            )}
          </div>
        )}
      </div>

      {/* ── Add/Edit Modal ──────────────────────────────────────────────────── */}
      {showModal && (
        <div style={{
          position: "fixed", top: 0, left: 0, right: 0, bottom: 0,
          background: "rgba(0,0,0,0.6)", zIndex: 2000,
          display: "flex", alignItems: "center", justifyContent: "center",
          padding: 24,
          backdropFilter: "blur(4px)"
        }} onClick={() => setShowModal(false)}>
          <div
            style={{
              background: t.surface,
              borderRadius: 16,
              border: `1px solid ${t.border}`,
              width: "100%", maxWidth: 440,
              maxHeight: "90vh",
              overflow: "auto",
              boxShadow: "0 24px 48px rgba(0,0,0,0.3)"
            }}
            onClick={e => e.stopPropagation()}
          >
            <div style={{ padding: "24px 24px 16px", borderBottom: `1px solid ${t.border}` }}>
              <h3 style={{ margin: 0, fontSize: 18, fontWeight: 700, color: t.text }}>
                {modalMode === "add" ? "Add Event" : "Edit Event"}
              </h3>
              <p style={{ margin: "4px 0 0", fontSize: 13, color: t.sub }}>
                {selectedDate && `${monthNames[selectedDate.month]} ${selectedDate.day}, ${selectedDate.year}`}
              </p>
            </div>

            <div style={{ padding: "20px 24px", display: "flex", flexDirection: "column", gap: 16 }}>
              <div>
                <label style={{ display: "block", fontSize: 12, fontWeight: 600, color: t.sub, marginBottom: 6, textTransform: "uppercase", letterSpacing: "0.05em" }}>Title</label>
                <input
                  type="text"
                  value={formData.title}
                  onChange={e => setFormData({ ...formData, title: e.target.value })}
                  placeholder="e.g., Hearing: State v. Sharma"
                  style={{
                    width: "100%", padding: "10px 14px", borderRadius: 8,
                    border: `1px solid ${t.border}`, background: t.bg, color: t.text,
                    fontSize: 14, fontFamily: "inherit"
                  }}
                />
              </div>

              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
                <div>
                  <label style={{ display: "block", fontSize: 12, fontWeight: 600, color: t.sub, marginBottom: 6, textTransform: "uppercase", letterSpacing: "0.05em" }}>Type</label>
                  <select
                    value={formData.type}
                    onChange={e => setFormData({ ...formData, type: e.target.value })}
                    style={{
                      width: "100%", padding: "10px 14px", borderRadius: 8,
                      border: `1px solid ${t.border}`, background: t.bg, color: t.text,
                      fontSize: 14, fontFamily: "inherit", cursor: "pointer"
                    }}
                  >
                    <option value="hearing">Hearing</option>
                    <option value="deadline">Deadline</option>
                  </select>
                </div>
                <div>
                  <label style={{ display: "block", fontSize: 12, fontWeight: 600, color: t.sub, marginBottom: 6, textTransform: "uppercase", letterSpacing: "0.05em" }}>Time</label>
                  <input
                    type="text"
                    value={formData.time}
                    onChange={e => setFormData({ ...formData, time: e.target.value })}
                    placeholder="e.g., 10:00 AM"
                    style={{
                      width: "100%", padding: "10px 14px", borderRadius: 8,
                      border: `1px solid ${t.border}`, background: t.bg, color: t.text,
                      fontSize: 14, fontFamily: "inherit"
                    }}
                  />
                </div>
              </div>

              <div>
                <label style={{ display: "block", fontSize: 12, fontWeight: 600, color: t.sub, marginBottom: 6, textTransform: "uppercase", letterSpacing: "0.05em" }}>Court / Location</label>
                <input
                  type="text"
                  value={formData.court}
                  onChange={e => setFormData({ ...formData, court: e.target.value })}
                  placeholder="e.g., Delhi High Court"
                  style={{
                    width: "100%", padding: "10px 14px", borderRadius: 8,
                    border: `1px solid ${t.border}`, background: t.bg, color: t.text,
                    fontSize: 14, fontFamily: "inherit"
                  }}
                />
              </div>
            </div>

            <div style={{ padding: "16px 24px 24px", display: "flex", gap: 10, justifyContent: "flex-end", borderTop: `1px solid ${t.border}` }}>
              <button
                onClick={() => setShowModal(false)}
                style={{
                  padding: "10px 18px", borderRadius: 8, border: `1px solid ${t.border}`,
                  background: "transparent", color: t.text, fontSize: 13, fontWeight: 600,
                  cursor: "pointer", fontFamily: "inherit"
                }}
              >
                Cancel
              </button>
              <button
                onClick={saveEvent}
                style={{
                  padding: "10px 18px", borderRadius: 8, border: "none",
                  background: "#ea580c", color: "#fff", fontSize: 13, fontWeight: 700,
                  cursor: "pointer", fontFamily: "inherit"
                }}
              >
                {modalMode === "add" ? "Add Event" : "Save Changes"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
